// 解析AI输出的JSON并标准化
const output = [];
for (const item of $input.all()) {
  try {
    const aiResult = typeof item.json.output === 'string'
      ? JSON.parse(item.json.output)
      : item.json.output;

    output.push({
      json: {
        id: item.json.guid || item.json.link || Date.now().toString(36) + Math.random().toString(36).slice(2),
        title: aiResult.title_cleaned || item.json.title,
        source: item.json.source || item.json['dc:creator'] || '未知',
        category: aiResult.category || '其他',
        stars: aiResult.star || 2,
        time: formatTime(item.json.pubDate || item.json.published),
        summary: aiResult.summary_ai || '',
        tags: aiResult.tags || [],
        selfStock: !!aiResult.is_self_stock,
        duplicate: !!aiResult.is_duplicate,
        confidence: aiResult.confidence || 0,
        url: item.json.link || item.json.url || '#',
        fetchedAt: new Date().toISOString()
      }
    });
  } catch(e) {
    // 解析失败时保留原始数据，给低分
    output.push({
      json: {
        id: item.json.guid || Date.now().toString(36),
        title: item.json.title,
        source: item.json['dc:creator'] || '未知',
        category: '其他',
        stars: 1,
        time: formatTime(item.json.pubDate),
        summary: '[AI解析失败] ' + (item.json.description || '').slice(0, 100),
        tags: [],
        selfStock: false,
        duplicate: false,
        confidence: 0,
        url: item.json.link || '#',
        fetchedAt: new Date().toISOString()
      }
    });
  }
}

function formatTime(dateStr) {
  if (!dateStr) return new Date().toTimeString().slice(0,5);
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return new Date().toTimeString().slice(0,5);
  return d.toTimeString().slice(0,5);
}

return output;

// 去重：移除重复条目并保留最新版
const items = $input.all();
const seen = new Map();
const deduped = [];

for (const item of items) {
  const key = (item.json.title || '').toLowerCase().replace(/\s+/g, '');
  if (!seen.has(key)) {
    seen.set(key, item);
    deduped.push(item);
  } else {
    // 保留星级更高的版本
    const existing = seen.get(key);
    if ((item.json.stars || 0) > (existing.json.stars || 0)) {
      const idx = deduped.indexOf(existing);
      deduped[idx] = item;
      seen.set(key, item);
    }
  }
}

return deduped;

