// 生成每日简报摘要
const items = $input.all();
const major = items.filter(i => i.json.stars >= 4).sort((a,b) => b.json.stars - a.json.stars);
const selfStock = items.filter(i => i.json.selfStock);

const brief = `# ${new Date().toLocaleDateString('zh-CN', {year:'numeric',month:'long',day:'numeric',weekday:'long'})} 要闻简报

` +
`## 🌟 今日重大事件 (${major.length}件)

` +
major.map((i,n => `${n+1}. **[${i.json.stars}★]** ${i.json.title}
   ${i.json.summary}
`)).join('
') +
(selfStock.length ? `
## ⚡ 自选股相关 (${selfStock.length}件)

` +
selfStock.map(i => `- ${i.json.title}
`).join('
') : '') +
`
---
*由 NewsPulse AI 自动生成 · ${new Date().toLocaleString('zh-CN')}*`;

return [{ json: { content: brief } }];
